package com.cpf.integration.iso8583;import java.nio.charset.StandardCharsets;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;public final class CpfIso8583HmacMacProvider {private final byte[] key;private final int length;public CpfIso8583HmacMacProvider(byte[] key,int length){if(key==null||key.length<32||length<4||length>32)throw new IllegalArgumentException("strong key and MAC length 4..32 required");this.key=key.clone();this.length=length;}public byte[] mac(byte[] message){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key,"HmacSHA256"));return java.util.Arrays.copyOf(m.doFinal(message),length);}catch(Exception ex){throw new IllegalStateException(ex);}}public boolean verify(byte[] message,byte[] expected){return java.security.MessageDigest.isEqual(mac(message),expected);}}
